CREATE TABLE ContaCliente(id_cliente INT UNSIGNED PRIMARY KEY,senha_hash VARCHAR(255) NOT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente)) ENGINE=InnoDB;
CREATE TABLE SessaoPortal(token_hash CHAR(64) PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,csrf_token VARCHAR(64) NOT NULL,expira_em DATETIME NOT NULL,FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente),INDEX(expira_em)) ENGINE=InnoDB;
CREATE TABLE TokenPortal(token_hash CHAR(64) PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,expira_em DATETIME NOT NULL,utilizado_em DATETIME NULL,FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente)) ENGINE=InnoDB;
CREATE TABLE AuditoriaCliente(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,acao VARCHAR(80) NOT NULL,recurso VARCHAR(80),criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente),INDEX(criado_em)) ENGINE=InnoDB;
ALTER TABLE EmailOutbox ADD tentativas INT UNSIGNED NOT NULL DEFAULT 0,ADD proxima_tentativa DATETIME NULL;
CREATE TABLE PoliticaFalta(id TINYINT UNSIGNED PRIMARY KEY,consumir_sessao BOOLEAN NOT NULL DEFAULT FALSE,justificativa VARCHAR(500) NOT NULL,atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,id_autor INT UNSIGNED NULL,FOREIGN KEY(id_autor) REFERENCES Usuario(id_usuario)) ENGINE=InnoDB;
INSERT INTO PoliticaFalta(id,justificativa) VALUES(1,'Política inicial: faltas não consomem sessões.');
ALTER TABLE EventoAgenda ADD sessao_consumida BOOLEAN NOT NULL DEFAULT FALSE,ADD politica_aplicada VARCHAR(500) NULL,MODIFY id_autor INT UNSIGNED NULL;
CREATE TABLE VinculoClinico(id_vinculo INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,id_profissional INT UNSIGNED NOT NULL,ativo BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(id_cliente,id_profissional),FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente),FOREIGN KEY(id_profissional) REFERENCES Profissional(id_profissional)) ENGINE=InnoDB;
CREATE TABLE PedidoPrivacidade(id_pedido INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,tipo ENUM('acesso','correcao','exclusao') NOT NULL,descricao VARCHAR(2000) NOT NULL,status ENUM('aberto','em_analise','atendido','indeferido') NOT NULL DEFAULT 'aberto',resposta VARCHAR(2000),data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_cliente) REFERENCES Cliente(id_cliente)) ENGINE=InnoDB;
